				fz_throw(ctx, FZ_ERROR_GENERIC, "cannot load object stream containing object (%d 0 R)", num);
			if (!x->obj)
			{
				x->type = 'f';
				orig_x->type = 'f';
				if (doc->repair_attempted)
					fz_throw(ctx, FZ_ERROR_GENERIC, "object (%d 0 R) was not found in its object stream", num);
				goto perform_repair;
			}
		}
	}
